import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const LeaderboardPage = () => {
  const { user } = useAuth();
  const [leaderboards, setLeaderboards] = useState({
    biggestWins: [],
    mostWagered: [],
    highestProfit: [],
    mostCoinflips: [],
    mostBlackjackGames: []
  });
  const [activeTab, setActiveTab] = useState('biggestWins');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchLeaderboards = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/leaderboard`);
        const data = await response.json();

        setLeaderboards(data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching leaderboards:', error);
        setLoading(false);
      }
    };

    fetchLeaderboards();
  }, []);

  const getRankIcon = (rank) => {
    switch(rank) {
      case 1: return '🥇';
      case 2: return '🥈';
      case 3: return '🥉';
      default: return `#${rank}`;
    }
  };

  const renderLeaderboard = (data, valueKey) => {
    return (
      <div className="leaderboard-table">
        <table className="table">
          <thead>
            <tr>
              <th>Rank</th>
              <th>Player</th>
              <th>{valueKey === 'count' ? 'Games' : 'Amount'}</th>
            </tr>
          </thead>
          <tbody>
            {data.map((entry, index) => {
              const user = entry.user || entry;
              return (
                <tr key={index}>
                  <td><span className="rank-icon">{getRankIcon(index + 1)}</span></td>
                  <td>
                    <div className="player-info">
                      <img 
                        src={user.avatar || '/default-avatar.png'} 
                        alt={user.displayName} 
                        className="player-avatar"
                        onError={(e) => {
                          e.target.src = '/default-avatar.png';
                        }}
                      />
                      <span className="player-name">{user.displayName}</span>
                    </div>
                  </td>
                  <td>
                    {valueKey === 'count' ? 
                      entry.count || entry[valueKey]?.toLocaleString() :
                      (entry[valueKey] || user[valueKey])?.toLocaleString()
                    } {valueKey !== 'count' ? 'AMP' : ''}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading leaderboard...</p>
      </div>
    );
  }

  return (
    <div className="leaderboard-page">
      <div className="page-header">
        <h1>Leaderboard</h1>
      </div>

      <div className="leaderboard-tabs">
        <button 
          className={`tab-button ${activeTab === 'biggestWins' ? 'active' : ''}`}
          onClick={() => setActiveTab('biggestWins')}
        >
          Biggest Wins
        </button>
        <button 
          className={`tab-button ${activeTab === 'mostWagered' ? 'active' : ''}`}
          onClick={() => setActiveTab('mostWagered')}
        >
          Most Wagered
        </button>
        <button 
          className={`tab-button ${activeTab === 'highestProfit' ? 'active' : ''}`}
          onClick={() => setActiveTab('highestProfit')}
        >
          Highest Profit
        </button>
        <button 
          className={`tab-button ${activeTab === 'mostCoinflips' ? 'active' : ''}`}
          onClick={() => setActiveTab('mostCoinflips')}
        >
          Most Coinflips
        </button>
        <button 
          className={`tab-button ${activeTab === 'mostBlackjackGames' ? 'active' : ''}`}
          onClick={() => setActiveTab('mostBlackjackGames')}
        >
          Most Blackjack Games
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'biggestWins' && renderLeaderboard(leaderboards.biggestWins, 'balance')}
        {activeTab === 'mostWagered' && renderLeaderboard(leaderboards.mostWagered, 'totalDeposited')}
        {activeTab === 'highestProfit' && renderLeaderboard(leaderboards.highestProfit, 'balance')}
        {activeTab === 'mostCoinflips' && renderLeaderboard(leaderboards.mostCoinflips, 'count')}
        {activeTab === 'mostBlackjackGames' && renderLeaderboard(leaderboards.mostBlackjackGames, 'count')}
      </div>
    </div>
  );
};

export default LeaderboardPage;
